pub fn decode(data: &[u8]) -> Result<Request, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0, limit: DEPTH_LIMIT };
    r.skip_ws();
    let v = decode_request(&mut r)?;
    r.skip_ws();
    if r.pos < r.buf.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(v)
}

fn named_encode_constraints(v: &Constraints, depth: i32) -> Result<Vec<u8>, Refusal> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let mut out = Vec::new();
        enc_constraints(&mut out, v, depth);
        out
    })) {
        Ok(out) => Ok(out),
        Err(p) => match p.downcast::<Refusal>() {
            Ok(e) => Err(*e),
            Err(p) => std::panic::resume_unwind(p),
        },
    }
}

